{
  "items": [
    {
      "name": "Real.log_sqrt",
      "type": " {x : ℝ} (hx : 0 ≤ x) : Real.log √x = Real.log x / 2",
      "module": "Mathlib.Analysis.SpecialFunctions.Log.Basic"
    },
    {
      "name": "strictConcaveOn_sqrt_mul_log_Ioi",
      "type": " : StrictConcaveOn ℝ (Set.Ioi 1) fun x => √x * Real.log x",
      "module": "Mathlib.Analysis.Convex.SpecificFunctions.Deriv"
    },
    {
      "name": "deriv_sqrt_mul_log",
      "type": " (x : ℝ) : deriv (fun x => √x * Real.log x) x = (2 + Real.log x) / (2 * √x)",
      "module": "Mathlib.Analysis.Convex.SpecificFunctions.Deriv"
    },
    {
      "name": "deriv_sqrt_mul_log'",
      "type": " : (deriv fun x => √x * Real.log x) = fun x => (2 + Real.log x) / (2 * √x)",
      "module": "Mathlib.Analysis.Convex.SpecificFunctions.Deriv"
    },
    {
      "name": "deriv2_sqrt_mul_log",
      "type": " (x : ℝ) : deriv^[2] (fun x => √x * Real.log x) x = -Real.log x / (4 * √x ^ 3)",
      "module": "Mathlib.Analysis.Convex.SpecificFunctions.Deriv"
    },
    {
      "name": "hasDerivAt_sqrt_mul_log",
      "type": " {x : ℝ} (hx : x ≠ 0) : HasDerivAt (fun x => √x * Real.log x) ((2 + Real.log x) / (2 * √x)) x",
      "module": "Mathlib.Analysis.Convex.SpecificFunctions.Deriv"
    },
    {
      "name": "Real.log_doublingGamma_eq",
      "type": " : Set.EqOn (Real.log ∘ Real.doublingGamma) (fun s => Real.log (Real.Gamma (s / 2)) + Real.log (Real.Gamma (s / 2 + 1 / 2)) + s * Real.log 2 - Real.log (2 * √Real.pi)) (Set.Ioi 0)",
      "module": "Mathlib.Analysis.SpecialFunctions.Gamma.BohrMollerup"
    },
    {
      "name": "Real.hasDerivAt_Gamma_one_half",
      "type": " : HasDerivAt Real.Gamma (-√Real.pi * (Real.eulerMascheroniConstant + 2 * Real.log 2)) (1 / 2)",
      "module": "Mathlib.NumberTheory.Harmonic.GammaDeriv"
    }
  ]
}
